## Why This Question Is Asked
Assesses the ability to design a constraint solver for 3-valued Kleene logic, demonstrating handling of partial knowledge and undefined states in logical policies.

## Key Concepts
- 3-valued truth tables for ¬, ∨, ∧, and →
- Arc-consistency enforcement on ternary domains
- Fixed-point propagation without backtracking

## Implementation
```javascript
const order = { 'F': 0, 'U': 1, 'T': 2 };

function not(v) {
  return v === 'F' ? 'T' : v === 'T' ? 'F' : 'U';
}

function max(a, b) {
  return order[a] > order[b] ? a : b;
}

function implies(a, b) {
  return max(not(a), b);
}

function supports(constraint, varIndex, value, currentAssignment) {
  const vars = ['A', 'B', 'C', 'D'];
  for (const val of ['F', 'U', 'T']) {
    currentAssignment[vars[varIndex]] = val;
    if (constraint(currentAssignment) !== 'F') return true;
  }
  return false;
}

function arcConsistency(domains, constraints) {
  let changed = true;
  while (changed) {
    changed = false;
    for (const constraint of constraints) {
      for (const [varName, domain] of Object.entries(domains)) {
        const filtered = domain.filter(val => 
          supports(constraint, varName, val, { A: domains.A[0], B: domains.B[0], C: domains.C[0], D: domains.D[0] })
        );
        if (filtered.length !== domain.length) {
          domains[varName] = filtered;
          changed = true;
        }
      }
    }
  }
  return domains;
}
```

